int parse_db_result(const char* result_data, size_t result_len, struct db_record* record) {
    if (!result_data || !record || result_len == 0) {
        return -1; // 参数错误
    }

    // 检查是否有足够的数据来解析基本头部信息
    if (result_len < sizeof(int)) {
        return -1; // 数据长度不足
    }

    size_t offset = 0;

    // 解析ID字段 (假设ID是4字节整数)
    if (offset + sizeof(int) > result_len) {
        return -1;
    }
    memcpy(&(record->id), result_data + offset, sizeof(int));
    offset += sizeof(int);

    // 解析field1 (假设格式是长度+字符串)
    if (offset + sizeof(uint8_t) > result_len) {
        return -1;
    }
    uint8_t field1_len = *(uint8_t*)(result_data + offset);
    offset += sizeof(uint8_t);

    if (offset + field1_len > result_len) {
        return -1;
    }
    if (field1_len >= sizeof(record->field1)) {
        field1_len = sizeof(record->field1) - 1; // 确保不会溢出
    }
    memcpy(record->field1, result_data + offset, field1_len);
    record->field1[field1_len] = '\0'; // 确保字符串结束
    offset += field1_len;

    // 解析field2 (假设格式是长度+字符串)
    if (offset + sizeof(uint8_t) > result_len) {
        return -1;
    }
    uint8_t field2_len = *(uint8_t*)(result_data + offset);
    offset += sizeof(uint8_t);

    if (offset + field2_len > result_len) {
        return -1;
    }
    if (field2_len >= sizeof(record->field2)) {
        field2_len = sizeof(record->field2) - 1; // 确保不会溢出
    }
    memcpy(record->field2, result_data + offset, field2_len);
    record->field2[field2_len] = '\0'; // 确保字符串结束

    return 0; // 解析成功
}
